import java.util.ArrayList;
import java.util.List;

public class Solution {
    static class BST {
        private static class Node {
            int val;
            Node esq, dir;
            Node(int val) { this.val = val; }
        }

        private Node raiz;
        private int size;

        boolean inserir(int v) {
            if (buscar(v)) return false;
            raiz = inserir(raiz, v);
            size++;
            return true;
        }

        private Node inserir(Node n, int v) {
            if (n == null) return new Node(v);
            if (v < n.val) n.esq = inserir(n.esq, v);
            else n.dir = inserir(n.dir, v);
            return n;
        }

        boolean buscar(int v) {
            Node n = raiz;
            while (n != null) {
                if (v == n.val) return true;
                n = v < n.val ? n.esq : n.dir;
            }
            return false;
        }

        boolean remover(int v) {
            if (!buscar(v)) return false;
            raiz = remover(raiz, v);
            size--;
            return true;
        }

        // Folha → null; um filho → o filho; dois filhos → copia o sucessor e o remove da direita.
        private Node remover(Node n, int v) {
            if (v < n.val) n.esq = remover(n.esq, v);
            else if (v > n.val) n.dir = remover(n.dir, v);
            else {
                if (n.esq == null) return n.dir;
                if (n.dir == null) return n.esq;
                Node suc = n.dir;
                while (suc.esq != null) suc = suc.esq;
                n.val = suc.val;
                n.dir = remover(n.dir, suc.val);
            }
            return n;
        }

        List<Integer> emOrdem() {
            List<Integer> out = new ArrayList<>();
            emOrdem(raiz, out);
            return out;
        }

        private void emOrdem(Node n, List<Integer> out) {
            if (n == null) return;
            emOrdem(n.esq, out);
            out.add(n.val);
            emOrdem(n.dir, out);
        }

        int size() { return size; }
    }
}

