import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static Solution.BST arvore(int... vs) {
        var t = new Solution.BST();
        for (int v : vs) t.inserir(v);
        return t;
    }

    @Test void insereEBusca() {
        var t = arvore(50, 30, 70, 20, 40, 60, 80);
        assertTrue(t.buscar(40));
        assertFalse(t.buscar(45));
        assertFalse(t.inserir(30));
        assertEquals(7, t.size());
        assertEquals(List.of(20, 30, 40, 50, 60, 70, 80), t.emOrdem());
    }

    @Test void removeFolhaUmFilhoDoisFilhos() {
        var t = arvore(50, 30, 70, 20, 40, 60, 80, 65);
        assertTrue(t.remover(20));          // folha
        assertTrue(t.remover(60));          // um filho (65)
        assertTrue(t.remover(50));          // raiz com dois filhos
        assertEquals(List.of(30, 40, 65, 70, 80), t.emOrdem());
        assertFalse(t.buscar(50));
        assertTrue(t.buscar(65));
        assertEquals(5, t.size());
    }

    @Test void removerAusenteEEsvaziar() {
        var t = arvore(2, 1, 3);
        assertFalse(t.remover(9));
        t.remover(2); t.remover(1); t.remover(3);
        assertEquals(List.of(), t.emOrdem());
        assertEquals(0, t.size());
    }

    @Test void aleatorioContraTreeSet() {
        var rnd = new Random(7);
        var t = new Solution.BST();
        var ref = new TreeSet<Integer>();
        for (int i = 0; i < 20_000; i++) {
            int v = rnd.nextInt(2000);
            if (rnd.nextBoolean()) assertEquals(ref.add(v), t.inserir(v));
            else assertEquals(ref.remove(v), t.remover(v));
        }
        assertEquals(new ArrayList<>(ref), t.emOrdem());
    }
}

