public class Solution {
    static class Node {
        int val;
        Node esq, dir;
        Node(int val, Node esq, Node dir) { this.val = val; this.esq = esq; this.dir = dir; }
    }

    static boolean valida(Node raiz) {
        return valida(raiz, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    // Cada nó precisa ficar no intervalo aberto (min, max) herdado dos ancestrais.
    private static boolean valida(Node n, long min, long max) {
        if (n == null) return true;
        if (n.val <= min || n.val >= max) return false;
        return valida(n.esq, min, n.val) && valida(n.dir, n.val, max);
    }
}

