import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    private static Solution.Node n(int v, Solution.Node e, Solution.Node d) { return new Solution.Node(v, e, d); }
    private static Solution.Node f(int v) { return new Solution.Node(v, null, null); }

    @Test void validas() {
        assertTrue(Solution.valida(null));
        assertTrue(Solution.valida(n(5, n(3, f(1), f(4)), n(8, null, f(9)))));
    }

    @Test void netoForaDoLimite() {
        assertFalse(Solution.valida(n(5, n(3, null, f(7)), f(8))));
        assertFalse(Solution.valida(n(5, f(1), n(8, f(4), null))));
    }

    @Test void duplicataInvalida() {
        assertFalse(Solution.valida(n(5, f(5), null)));
    }

    @Test void extremosDeInt() {
        assertTrue(Solution.valida(n(0, f(Integer.MIN_VALUE), f(Integer.MAX_VALUE))));
        assertTrue(Solution.valida(f(Integer.MIN_VALUE)));
    }
}
